-- KPI aggregate queries written in Snowflake dialect.
-- Honest scope note: there is no live Snowflake account in this environment.
-- These statements are validated by transpiling them to DuckDB with sqlglot
-- and executing the transpiled form against the local telemetry table.
-- Table: telemetry_daily (columns as generated by generate_telemetry.py)

-- name: weekly_bookings
SELECT DATE_TRUNC('week', date) AS week_start,
       SUM(booking_completions) AS completions,
       SUM(revenue_gbp) AS revenue_gbp
FROM telemetry_daily
GROUP BY week_start
ORDER BY week_start;

-- name: monthly_activation
SELECT DATE_TRUNC('month', date) AS month_start,
       SUM(new_installs) AS installs,
       SUM(activations) AS activations,
       SUM(activations) / NULLIF(SUM(new_installs), 0) AS activation_rate
FROM telemetry_daily
GROUP BY month_start
ORDER BY month_start;
